@namespace sv_e32c4b777eae4ed082c1ecb552cccc33.Components.Settings
@using sv_e32c4b777eae4ed082c1ecb552cccc33.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p>Loading appearance settings…</p>
    }
    else
    {
        <div class="mb-4">
            <label class="form-label fw-bold">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var theme in _themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-bold" for="language">Language</label>
            <select class="form-select" id="language" @bind="_language" style="max-width:250px">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><strong>Live Preview</strong></div>
            <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyle()">
                <h5 style="margin-bottom: .5rem;">Preview Heading</h5>
                <p style="margin-bottom: .25rem;">This is how your content will look with the selected settings.</p>
                <button class="btn @(_theme == "Dark" ? "btn-light" : "btn-primary") btn-sm">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3" role="alert">@_successMessage</div>
        }
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("bg-dark text-light");
        else if (_theme == "Light") classes.Add("bg-light text-dark");
        else classes.Add("bg-body-secondary");
        return string.Join(' ', classes);
    }

    private string GetPreviewStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = _compactMode ? "0.5rem" : "1rem";
        return $"font-size:{size}; padding:{padding};";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _successMessage = "Appearance settings saved!";
    }
}

