@page "/settings"
@rendermode InteractiveServer
@namespace sv_e32c4b777eae4ed082c1ecb552cccc33.Components.Pages
@using sv_e32c4b777eae4ed082c1ecb552cccc33.Components.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="section => _activeSection = section" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0.375rem;
    padding: 0.6rem 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

::deep .settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .avatar-preview img {
    border: 3px solid #dee2e6;
    object-fit: cover;
}

